// ---------------------------------------------------------------------------
// THUẬT TOÁN TÌM KIẾM PHƯỜNG/XÃ CHÍNH THỨC (Official Ward Lookup)
// ---------------------------------------------------------------------------

/**
 * Ray Casting Point-in-Polygon cho bộ dữ liệu chuẩn quốc gia
 */
function isPointInOfficialPolygon(
  lat: number, lng: number, polygon: Array<[number, number]>
): boolean {
  if (!polygon || polygon.length < 3) return false;
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const yi = polygon[i][1], yj = polygon[j][1];
    if ((yi > lng) !== (yj > lng) &&
        lat < ((polygon[j][0] - polygon[i][0]) * (lng - yi)) / (yj - yi) + polygon[i][0]) {
      inside = !inside;
    }
  }
  return inside;
}

/**
 * Khoảng cách từ điểm tới cạnh đa giác (km)
 */
function distToEdgeKm(px: number, py: number, x1: number, y1: number, x2: number, y2: number): number {
  const dx = x2 - x1, dy = y2 - y1;
  const l2 = dx * dx + dy * dy;
  if (l2 === 0) return Math.hypot(px - x1, py - y1) * 111;
  const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / l2));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy)) * 111;
}

/**
 * Tìm phường/xã chính thức cho tọa độ GPS bất kỳ.
 * Cascade:
 *   1. Khớp chính xác Ray Casting đa giác chuẩn quốc gia
 *   2. Boundary edge snapping (dung sai ~150m) cho đơn ngay trên đường ranh giới
 */
export function findOfficialWardForCoordinate(
  lat: number, lng: number, toleranceKm = 0.15
): OfficialWardBoundary | null {
  // 1. Exact Ray Casting match
  for (const ward of OFFICIAL_WARD_BOUNDARIES) {
    if (isPointInOfficialPolygon(lat, lng, ward.boundaryPolygon)) {
      return ward;
    }
  }

  // 2. Edge snapping fallback for boundary streets
  let closest: OfficialWardBoundary | null = null;
  let minKm = Infinity;
  for (const ward of OFFICIAL_WARD_BOUNDARIES) {
    const poly = ward.boundaryPolygon;
    for (let i = 0; i < poly.length; i++) {
      const j = (i + 1) % poly.length;
      const d = distToEdgeKm(lat, lng, poly[i][0], poly[i][1], poly[j][0], poly[j][1]);
      if (d < minKm) { minKm = d; closest = ward; }
    }
  }
  return (closest && minKm <= toleranceKm) ? closest : null;
}
